const items=$input.all();
if(items.length!==1)throw new Error('ONE_ITEM_REQUIRED');
const b=items[0].json.body;
if(!b || typeof b.system!=='string' || typeof b.prompt!=='string' || typeof b.reservation_id!=='string')throw new Error('INVALID_INPUT');
if(!/^[a-f0-9-]{36}$/.test(b.reservation_id))throw new Error('INVALID_RESERVATION');
const bytes=Buffer.byteLength(b.system,'utf8')+Buffer.byteLength(b.prompt,'utf8');
if(bytes>23000 || !b.prompt.trim())throw new Error('INPUT_BOUND_EXCEEDED');
if(b.model!=='claude-haiku-5-5' || b.max_output_tokens!==2000)throw new Error('MODEL_BOUND_MISMATCH');
return [{json:{system:b.system,prompt:b.prompt,reservation_id:b.reservation_id,input_utf8_bytes:bytes}}];
